1: /**
2:  * dsh-token-guard —— 零依赖本地插件（与 dsh-mcp-gateway / dsh-agent-guard 同约束：
3:  * 装在 profile 之外，**不 import `@deepseek-ai/*`**，否则 profile 外解析不到）。
4:  *
5:  * 缺口：dsh-spill-policy 在 tools/post-execute 逐次裁剪大结果，但**显式跳过 read**
6:  * （`exec.name === "read"`），而 read 单次默认最多返回 50KB(≈12.5k token)——这些
7:  * 大 read 结果每一轮都随历史重发，是「消息占 ~81% 上下文」的主要来源之一。
8:  *
9:  * 本插件补上这块：对 read（以及配置的额外工具）的大结果，在**执行期**做头尾裁剪
10:  * + 自动落盘（复用 ctx.get("spillStore")），返回裁剪版 + 可回读路径。不改写非文本块，
11:  * 任一步失败都保留原文，绝不阻断工具。
12:  *
13:  * 与现有插件分工：
14:  *   - spill-policy      : 非 read 的大结果，>maxInlineTokens 落盘；
15:  *   - tool-result-pruner: 仅 compaction 触发后压历史；
16:  *   - token-guard（本插件）: read 的大结果，执行期落盘 + 头尾保留。
17:  */
18: 
19: /** Cordis 插件身份与注入。tools 提供 tools/post-execute 事件。 */
20: export const name = "token-guard";
21: export const inject = ["tools"];
22: 
23: /**
24:  * 无 schemastery 时的最小配置解析：合并默认值。
25:  * 注意：**不 export Config**——Cordis 会把导出的 Config 当作 schemastery schema 调
26:  * `.validate()`，零依赖插件无法提供，会导致加载失败。配置在 apply 内自行归一化。
27:  */
28: function normalizeConfig(input) {
29:   return {
30:     enabled: input?.enabled ?? true,
31:     readBudgetTokens: input?.readBudgetTokens ?? 4000,
32:     inlineTokens: input?.inlineTokens ?? 1500,
33:     extraTools: Array.isArray(input?.extraTools) ? input.extraTools : [],
34:   };
35: }
36: 
37: const GAP = { type: "text", text: "\n\n[... token-guard: middle pruned ...]\n\n" };
38: const CHARS_PER_TOKEN = 4;
39: 
40: /** 与 dsh-token-meter 一致的固定密度估算（粗略，仅用于判阈值，不需精确）。 */
41: function estimateText(text) {
42:   return Math.ceil(text.length / CHARS_PER_TOKEN);
43: }
44: 
45: function textBytes(text) {
46:   let bytes = 0;
47:   for (const ch of text) {
48:     const code = ch.codePointAt(0);
49:     bytes += code <= 0x7f ? 1 : code <= 0x7ff ? 2 : code <= 0xffff ? 3 : 4;
50:   }
51:   return bytes;
52: }
53: 
54: /** 保留内容只能由 text/image 块构成；含其它块就原样放过，避免破坏结构。 */
55: function retainable(content) {
56:   return Array.isArray(content) && content.every((b) => b && (b.type === "text" || b.type === "image"));
57: }
58: 
59: function priceBlock(block) {
60:   return block.type === "text" ? estimateText(block.text) + 4 : 4;
61: }
62: 
63: function priceContent(content) {
64:   return content.reduce((s, b) => s + priceBlock(b), 0);
65: }
66: 
67: /** 按 token 预算保留头尾，中间折成 GAP。返回 { head, tail, omittedBytes }。 */
68: function retainContent(content, budget) {
69:   const head = [];
70:   const tail = [];
71:   let first = 0;
72:   let last = content.length - 1;
73:   let headChars = 0;
74: 
75:   let remaining = Math.ceil(budget / 2);
76:   while (first <= last) {
77:     const block = content[first];
78:     const cost = priceBlock(block);
79:     if (cost <= remaining) { head.push(block); remaining -= cost; first++; continue; }
80:     if (block.type === "text") {
81:       const approx = Math.max(0, remaining) * CHARS_PER_TOKEN;
82:       const t = block.text.slice(0, approx);
83:       headChars = t.length;
84:       if (t.length) head.push({ type: "text", text: t });
85:     }
86:     break;
87:   }
88: 
89:   remaining = Math.floor(budget / 2);
90:   while (last >= first) {
91:     const original = content[last];
92:     const block = last === first && original.type === "text"
93:       ? { type: "text", text: original.text.slice(headChars) }
94:       : original;
95:     const cost = priceBlock(block);
96:     if (cost <= remaining) { tail.push(block); remaining -= cost; last--; continue; }
97:     if (block.type === "text") {
98:       const approx = Math.max(0, remaining) * CHARS_PER_TOKEN;
99:       const t = approx > 0 ? block.text.slice(block.text.length - approx) : "";
100:       if (t.length) tail.push({ type: "text", text: t });
101:     }
102:     break;
103:   }
104:   tail.reverse();
105: 
106:   const bytesOf = (blocks) => blocks.reduce((s, b) => s + (b.type === "text" ? textBytes(b.text) : 0), 0);
107:   return { head, tail, omittedBytes: bytesOf(content) - bytesOf(head) - bytesOf(tail) };
108: }
109: 
110: function formatNotice(omittedBytes, ref) {
111:   const locator = ref?.locator ?? "(unknown path)";
112:   const hint = ref?.retrievalHint ?? "Use read with offset/limit, or grep this path.";
113:   return `(Omitted ${omittedBytes} bytes. Full result stored at: ${locator}. ${hint})`;
114: }
115: 
116: function mergeText(blocks) {
117:   const out = [];
118:   for (const b of blocks) {
119:     const prev = out.at(-1);
120:     if (b.type === "text" && prev?.type === "text") prev.text += b.text;
121:     else out.push(b.type === "text" ? { ...b } : b);
122:   }
123:   return out;
124: }
125: 
126: function fullTextOf(content) {
127:   return content.map((b) => (b.type === "text" ? b.text : "")).join("");
128: }
129: 
130: const GREP_MATCH = /^\s*(?:Line\s+)?\d+:/;
131: const GREP_FILE_LINE = /^(.+?):(\d+):(.*)$/;
132: const GREP_NOTE = "(\u7ed3果过多，已截断。请缩小搜索范围或使用更精确的正则)";
133: const PWSH_WARN = "[警告] 工具产生了大量报错输出，可能包含许多与当前修改无关的既有错误。";
134: const BUILD_CMD = /\bnpm\s+run\s+lint\b|\bnpm\s+run\s+build\b|\bnpm\s+test\b/;
135: const ERROR_LINE = /\b(?:error|err!|failed|failure|exception)\b|✖|error TS\d+/i;
136: 
137: function grepStats(text) {
138:   const files = new Set();
139:   let matches = 0;
140:   let current = null;
141:   for (const line of text.split("\n")) {
142:     const located = line.match(GREP_FILE_LINE);
143:     if (located && !located[1].includes(" ")) {
144:       files.add(located[1]);
145:       matches += 1;
146:       continue;
147:     }
148:     if (GREP_MATCH.test(line)) {
149:       matches += 1;
150:       if (current) files.add(current);
151:       continue;
152:     }
153:     const header = line.trim();
154:     if (header && !header.includes(" ") && /[\\/]/.test(header)) current = header;
155:   }
156:   return { files: files.size, matches };
157: }
158: 
159: function capGrep(text) {
160:   const stats = grepStats(text);
161:   if (stats.files <= 10 && stats.matches <= 20) return null;
162:   const kept = [];
163:   const files = new Set();
164:   let matches = 0;
165:   let current = null;
166:   for (const line of text.split("\n")) {
167:     const located = line.match(GREP_FILE_LINE);
168:     const isMatch = Boolean(located && !located[1].includes(" ")) || GREP_MATCH.test(line);
169:     if (isMatch) {
170:       const file = located && !located[1].includes(" ") ? located[1] : current;
171:       if (file && !files.has(file) && files.size >= 10) break;
172:       if (matches >= 20) break;
173:       if (file) files.add(file);
174:       matches += 1;
175:     } else {
176:       const header = line.trim();
177:       if (header && !header.includes(" ") && /[\\/]/.test(header)) {
178:         if (files.size >= 10 && !files.has(header)) break;
179:         current = header;
180:       }
181:     }
182:     kept.push(line);
183:   }
184:   return `${kept.join("\n").replace(/\n+$/, "")}\n${GREP_NOTE}`;
185: }
186: 
187: function capPwsh(command, text) {
188:   if (!BUILD_CMD.test(String(command || ""))) return null;
189:   const lines = text.split("\n");
190:   const errors = lines.filter((line) => ERROR_LINE.test(line));
191:   if (errors.length <= 20) return null;
192:   const omitted = lines.length - 15;
193:   return [
194:     PWSH_WARN,
195:     ...lines.slice(0, 10),
196:     `... (省略 ${omitted} 行错误) ...`,
197:     ...lines.slice(-5),
198:   ].join("\n");
199: }
200: 
201: function capOrchestrate(text) {
202:   if (text.length <= 1000 || !/无法读取|示意/.test(text)) return null;
203:   return `${text.slice(0, 1000)}\n(结果不可用，已截断。请宿主重新规划，不要沿用无法读取或示意性内容。)`;
204: }
205: 
206: /** 超限时返回截断文本；未超限返回 null。 */
207: function cappedText(exec, text) {
208:   const toolName = exec?.name;
209:   if (toolName === "grep") return capGrep(text);
210:   if (toolName === "pwsh") return capPwsh(exec?.arguments?.command, text);
211:   if (toolName === "orchestrate") return capOrchestrate(text);
212:   if (toolName === "read") {
213:     const lines = text.split("\n");
214:     if (lines.length <= 500) return null;
215:     return lines.slice(0, 500).join("\n")
216:       + "\n[token-guard] read 已超过 500 行，其余已截断。请用 offset/limit 续读，或改用 grep 定位。";
217:   }
218:   if (toolName === "skill" && text.length > 2500) {
219:     return text.slice(0, 2500)
220:       + "\n[token-guard] skill 正文已截断。只保留前 2500 字，按已给出的步骤执行，不要为了补全文再整篇重读。";
221:   }
222:   return null;
223: }
224: 
225: export function apply(ctx, rawConfig) {
226:   const config = normalizeConfig(rawConfig);
227:   if (!config.enabled) return;
228:   const budget = config.inlineTokens;
229:   if (!Number.isSafeInteger(budget) || budget < 0) {
230:     throw new Error(`token-guard: inlineTokens must be a non-negative integer (got ${budget})`);
231:   }
232:   const threshold = config.readBudgetTokens;
233:   const watched = new Set(["read", ...config.extraTools]);
234: 
235:   ctx.on("tools/post-execute", async (exec, result, next) => {
236:     const decision = await next();
237:     if (decision.kind !== "accept" || Object.hasOwn(decision, "value")) return decision;
238:     let content = decision.content ?? result.content;
239:     if (!retainable(content) || content.length === 0) return decision;
240:     const shortened = cappedText(exec, fullTextOf(content));
241:     if (shortened) {
242:       content = [{ type: "text", text: shortened }];
243:       if (!watched.has(exec.name) || priceContent(content) <= threshold) {
244:         return { kind: "accept", content };
245:       }
246:     }
247:     if (!watched.has(exec.name)) return decision;
248:     if (priceContent(content) <= threshold) return decision;
249: 
250:     try {
251:       const owner = exec.agent?.session.header.id;
252:       if (owner === undefined) throw new Error(`no session owner for ${exec.name}`);
253:       const spillStore = ctx.get("spillStore");
254:       if (spillStore === undefined) throw new Error("no ctx.spillStore backend loaded");
255:       const ref = await spillStore.saveText({
256:         owner: { sessionId: owner },
257:         source: { kind: "tool", toolName: exec.name, callId: exec.callId, label: "result" },
258:         suggestedName: `${exec.name}.txt`,
259:         content: fullTextOf(content),
260:       });
261:       const retained = retainContent(content, budget);
262:       const notice = { type: "text", text: `\n\n${formatNotice(retained.omittedBytes, ref)}` };
263:       const rebuilt = retained.head.length + retained.tail.length === 0
264:         ? [notice]
265:         : mergeText([...retained.head, GAP, ...retained.tail, notice]);
266:       return { kind: "accept", content: rebuilt };
267:     } catch (error) {
268:       ctx.logger?.warn(`token-guard: ${String(error)}; keeping the inline content`);
269:       return decision;
270:     }
271:   }, { prepend: true });
272: }

