1: /**
2:  * dsh-cost-meter —— 会话内实时成本/未命中提醒（零依赖本地插件）。
3:  *
4:  * 与 dsh-mcp-gateway / dsh-agent-guard 同约束：装在 profile 之外，**不 import @deepseek-ai/***。
5:  *
6:  * 作用：把「60% 窗口收尾 / 每步未命中过高 / 累计等效成本过高」从口头规则变成**运行时自动提醒**。
7:  *   - 监听 `session/event`，从 assistant/message 的 usage 累加 uncached / cacheRead / output；
8:  *   - 每次 `agent/pre-step` 前检查阈值，越过就在本轮 messages 末尾追加一条 notice 提示模型收尾/换会话/别再整读；
9:  *   - 同一阈值只提醒一次（按会话记录），避免每步刷屏。
10:  *
11:  * 等效成本口径：cacheRead×0.1 + uncached + output×4。
12:  * 0.1 与 4 是假设倍率，待按实际计费校准，不是某次会话日志的证据。
13:  * 三键全 0 且没有 cacheReadTokens 的 usage 视为 absent：不进等效成本，只计 absentSteps。
14:  */
15: 
16: import { randomUUID } from "node:crypto";
17: 
18: export const name = "cost-meter";
19: export const inject = [];
20: 
21: /**
22:  * 配置归一化（零依赖，不 export Config 以免被 Cordis 当 schemastery schema 校验）。
23:  */
24: function normalizeConfig(input) {
25:   return {
26:     enabled: input?.enabled ?? true,
27:     sessionEquivBudget: input?.sessionEquivBudget ?? 8_000_000,
28:     // 单步未命中门槛 10k（2026-11-10 由 15k 下调，实测 >15k 时单步 reasoning 已失控）。
29:     perStepUncachedBudget: input?.perStepUncachedBudget ?? 10_000,
30:     // 单步 output 门槛 3k（2026-11-10 bug6369：step 46/49/50 单步 output ~10k，
31:     // 全耗在反复推翻自己的 reasoning 上——缺事实时不该脑内演算）。
32:     perStepOutputBudget: input?.perStepOutputBudget ?? 3_000,
33:     // 纯文本且无工具调用：1500 即疑似自我辩论（有工具的长输出仍走 3k）。
34:     bareReasoningBudget: input?.bareReasoningBudget ?? 1_500,
35:     sessionUncachedBudget: input?.sessionUncachedBudget ?? 3_000_000,
36:     // 比 800 万更早的两档。15 万 ≈ 10 个单步未命中预算，或约两步 65k 级 cache 重读（按 0.1 倍率）。
37:     // 100 万比现有 800 万低一个数量级，避免累计档只在会话末期响一次。
38:     sessionEquivEarly: input?.sessionEquivEarly ?? 150_000,
39:     sessionEquivMid: input?.sessionEquivMid ?? 1_000_000,
40:   };
41: }
42: 
43: // 0.1 / 4：假设倍率，待计费校准。
44: const equivOf = (u) => (u.cacheRead || 0) * 0.1 + (u.uncached || 0) + (u.output || 0) * 4;
45: const fmt = (n) => n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(0) + 'k' : String(Math.round(n));
46: 
47: /**
48:  * 从 assistant/message 的 data.usage 取数。
49:  * 三键全 0 且没有 cacheReadTokens：absent，不当成零成本。
50:  * 带 cacheReadTokens 的显式 0（四键）仍是真实记账。
51:  */
52: /** 能看到 content 才判定；看不到返回 unknown，避免误报。 */
53: export function classifyAssistant(event) {
54:   const d = event?.data ?? event ?? {};
55:   const content = d.content ?? d.message?.content;
56:   if (!Array.isArray(content)) return "unknown";
57:   const tool = content.some((b) => b && (b.type === "tool_use" || b.type === "toolCall" || b.type === "functionCall" || b.type === "tool_call"));
58:   return tool ? "tool" : "text";
59: }
60: 
61: function readUsage(event) {
62:   const d = event?.data ?? event;
63:   const u = d?.usage;
64:   if (!u) return undefined;
65:   const hasCacheRead = Object.prototype.hasOwnProperty.call(u, "cacheReadTokens")
66:     || Object.prototype.hasOwnProperty.call(u, "cacheRead");
67:   const absent = !hasCacheRead
68:     && u.uncachedInputTokens === undefined
69:     && u.inputTokens === 0
70:     && u.outputTokens === 0
71:     && (u.totalTokens === 0 || u.totalTokens === undefined);
72:   if (absent) return { absent: true };
73:   return {
74:     absent: false,
75:     uncached: u.uncachedInputTokens ?? u.inputTokens ?? 0,
76:     cacheRead: u.cacheReadTokens ?? u.cacheRead ?? 0,
77:     output: u.outputTokens ?? 0,
78:   };
79: }
80: 
81: let latestAcc;
82: 
83: /** 测试与排查：最近一次 enabled apply 的会话累计。 */
84: export function inspect(sessionId) {
85:   const a = latestAcc?.get(sessionId);
86:   if (!a) return undefined;
87:   return {
88:     uncached: a.uncached,
89:     cacheRead: a.cacheRead,
90:     output: a.output,
91:     lastOutput: a.lastOutput,
92:     steps: a.steps,
93:     absentSteps: a.absentSteps,
94:     equiv: equivOf(a),
95:     fired: [...a.fired],
96:   };
97: }
98: 
99: export function apply(ctx, rawConfig) {
100:   const config = normalizeConfig(rawConfig);
101:   if (!config.enabled) return;
102: 
103:   // sessionId -> { uncached, cacheRead, output, steps, absentSteps, fired:Set }
104:   const acc = new Map();
105:   latestAcc = acc;
106: 
107:   ctx.on("session/event", (session, event) => {
108:     if (event?.type !== "assistant/message") return;
109:     const u = readUsage(event);
110:     if (!u) return;
111:     const id = session?.header?.id ?? session?.id;
112:     if (id === undefined) return;
113:     let a = acc.get(id);
114:     if (!a) {
115:       a = { uncached: 0, cacheRead: 0, output: 0, steps: 0, absentSteps: 0, lastUncached: 0, lastOutput: 0, lastBare: false, bareCount: 0, bigMissStreak: 0, committed: false, optimized: false, closing: false, fired: new Set() };
116:       acc.set(id, a);
117:     }
118:     if (u.absent) {
119:       a.absentSteps += 1;
120:       return;
121:     }
122:     a.uncached += u.uncached;
123:     a.cacheRead += u.cacheRead;
124:     a.output += u.output;
125:     a.steps += 1;
126:     a.lastUncached = u.uncached;
127:     a.lastOutput = u.output;
128:     a.lastBare = classifyAssistant(event) === "text" && u.output > config.bareReasoningBudget;
129:     // 连续纯推理步计数：只有「保持纯推理」才累加，一旦出现工具调用/正常步就清零。
130:     // 审计 P0：同一 turn 连续 2 个无工具调用步后必须升级为硬性「下一步必须调工具」，
131:     // 而不是每步都发同一句软提示（软提示实测拦不住 3–8k 的反复自我辩论）。
132:     a.bareStreak = a.lastBare ? (a.bareStreak || 0) + 1 : 0;
133:     if (a.lastBare) a.bareCount += 1;
134:     // 连续大未命中：第一次只提醒，第二次起把「提示」改成「下一步必须是取数」。
135:     a.bigMissStreak = u.uncached > config.perStepUncachedBudget ? (a.bigMissStreak || 0) + 1 : 0;
136:   });
137: 
138:   ctx.on("session/event", (session, event) => {
139:     const id = session?.header?.id ?? session?.id;
140:     if (id === undefined) return;
141:     const a = acc.get(id);
142:     if (!a) return;
143:     const type = String(event?.type ?? "");
144:     const d = event?.data ?? {};
145:     const toolName = d.name ?? d.tool ?? d.toolName ?? "";
146:     const blob = JSON.stringify(d.arguments ?? d.input ?? d.args ?? d.command ?? "");
147:     if (/pwsh/i.test(toolName) && /git\s+commit/.test(blob)) a.committed = true;
148:     if (/token-optimizer/.test(blob) || /token-optimizer/.test(toolName)) a.optimized = true;
149:     const reason = d.reason ?? d.status ?? "";
150:     if ((type === "turn/end" || type === "agent/turn-end" || type === "turn/completed") && reason === "completed" && a.committed && !a.optimized) {
151:       a.closing = true;
152:     }
153:   });
154: 
155:   const notice = (text, summary) => ({
156:     // 复刻 createMessage 的最小形状（role + source + 稳定 id），零依赖构造合法 user 消息。
157:     id: randomUUID(),
158:     role: "user",
159:     content: [{ type: "text", text }],
160:     source: { kind: "cost-meter", form: "notice", summary },
161:   });
162: 
163:   ctx.on("agent/pre-step", ({ agent, messages }, next) => {
164:     const id = agent?.session?.header?.id ?? agent?.session?.id;
165:     const a = id !== undefined ? acc.get(id) : undefined;
166:     if (!a) return next();
167: 
168:     const equiv = equivOf(a);
169:     // 本 turn 早先已有过无工具超长步，才给带工具的超预算步加上“下一步必须调工具”。
170:     const priorBare = a.bareCount > (a.lastBare ? 1 : 0);
171:     const overOutput = a.lastOutput > config.perStepOutputBudget;
172:     const outputText = priorBare
173:       ? `[cost-meter] 上一步已超预算，output ${fmt(a.lastOutput)} tokens（>${fmt(config.perStepOutputBudget)}）。下一步第一件事必须是工具调用，禁止再并列 Option 1/2/3。`
174:       : `[cost-meter] 上一步 output ${fmt(a.lastOutput)} tokens（>${fmt(config.perStepOutputBudget)}）。`;
175:     const checks = [
176:       ["perStep", a.lastUncached > config.perStepUncachedBudget && a.bigMissStreak < 2,
177:         `[cost-meter] 上一步未命中 ${fmt(a.lastUncached)} tokens（>${fmt(config.perStepUncachedBudget)}），极高。典型成因按概率排序：① 全仓/容器级 grep——缩到 src/views/<模块> 再搜；② 缺真实值在脑内演算——先查一条 SQL / 一个接口返回；③ 大文件整读——grep 定位后 read offset/limit。先判断自己属于哪种，再动下一步。`],
178:       ["perStepLookup", a.bigMissStreak >= 2,
179:         `[cost-meter] 连续 ${a.bigMissStreak} 步未命中 >${fmt(config.perStepUncachedBudget)}，提醒没改掉走势。下一步第一件事必须是一次取数：一条 SQL（先 ALL_TAB_COLUMNS / 一行样本）、或带 offset/limit 的窄读、或缩到模块的 grep。禁止再整读、禁止再全仓搜、禁止再推演。`],
180:       ["perStepOutput", overOutput && !priorBare, outputText],
181:       ["perStepOutputAfterA", overOutput && priorBare, outputText],
182:       ["bareReasoning", a.lastBare && a.bareStreak < 2,
183:         `[reasoning-watchdog] 上一步输出 ${fmt(a.lastOutput)} tokens 且无工具调用，疑似自我辩论。停止推演：调一次工具取事实，或直接下结论。`],
184:       // 审计 P0：连续第 2 个纯推理步起升级为硬指令。插件层无法真正下调 reasoningEffort
185:       // （reasoningEffort 在 turn 开始时已固定，pre-step 只能在 enter/reject 间选），
186:       // 所以这里用「下一步第一件事必须是工具调用」把空转截断在行为层。
187:       ["bareReasoningEscalate", a.lastBare && a.bareStreak >= 2,
188:         `[reasoning-watchdog] 已连续 ${a.bareStreak} 步无工具调用（每步 >${fmt(config.bareReasoningBudget)} tokens，当前 ${fmt(a.lastOutput)}）。这是「推理代替取数」的硬信号：下一步第一件事必须是工具调用——查一条数据 / 一次窄读 / 一次 grep 定位。禁止再列 Option 1/2/3，禁止再自我辩论；若确实无法推进就直接下结论收尾。`],
189:       ["closingCheck", a.closing,
190:         `[closing-check] 收尾自查未做：本轮有提交，未见 token-optimizer 记录。`],
191:       ["sessionUncached", a.uncached > config.sessionUncachedBudget,
192:         `[cost-meter] 本会话累计未命中 ${fmt(a.uncached)} tokens（>${fmt(config.sessionUncachedBudget)}）。成本已高，收窄任务范围、避免重复整读，必要时开新会话。`],
193:       ["sessionEquivEarly", equiv > config.sessionEquivEarly,
194:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivEarly)}，含 cache 重读；另有 ${a.absentSteps} 步没有用量）。先收窄读取，别等单步未命中才停。`],
195:       ["sessionEquivMid", equiv > config.sessionEquivMid,
196:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivMid)}）。已明显高于单步预算，准备收尾或换会话。`],
197:       ["sessionEquiv", equiv > config.sessionEquivBudget,
198:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivBudget)}，含 ${a.steps} 步）。接近收尾线：尽快给出结论或拆分到新会话，别用 compaction 硬撑。`],
199:     ];
200:     // 只看上一步的规则：每步都可能再超，不能被会话级 fired 吞掉。
201:     const repeatable = new Set(["perStepOutput", "perStepOutputAfterA", "bareReasoning", "bareReasoningEscalate", "perStepLookup"]);
202:     const extra = [];
203:     for (const [key, hit, text] of checks) {
204:       if (!hit) continue;
205:       if (!repeatable.has(key) && a.fired.has(key)) continue;
206:       a.fired.add(key);
207:       extra.push(notice(text, `cost-meter ${key}`));
208:     }
209:     if (extra.length === 0) return next();
210:     return next().then((decision) => {
211:       if (decision?.kind && decision.kind !== "enter") return decision;
212:       const base = decision?.messages ?? messages ?? [];
213:       return { ...(decision ?? {}), kind: "enter", messages: [...base, ...extra] };
214:     });
215:   });
